def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    cols = [c for c in np.unique(g) if c != bg]
    occ = None
    for c in cols:
        ys, xs = np.where(g == c)
        if (ys.max()-ys.min()+1)*(xs.max()-xs.min()+1) == len(ys):
            if occ is None or len(ys) > (g == occ).sum():
                occ = c
    shape = [c for c in cols if c != occ][0]
    hidden = (g == occ)
    sm = (g == shape)
    out = g.copy()
    out[hidden] = bg
    emit(out, "Remove the solid occluding rectangle, leaving background where it was.")
    hy, hx = np.where(hidden)
    best = None
    for axis in ('v', 'h'):
        n = W if axis == 'v' else H
        for s in range(0, 2*n - 1):  # mirror: i -> s - i
            ok = True
            for y, x in zip(hy, hx):
                my, mx = (y, s - x) if axis == 'v' else (s - y, x)
                if not (0 <= my < H and 0 <= mx < W) or hidden[my, mx]:
                    ok = False; break
            if not ok:
                continue
            match = 0
            for y, x in zip(*np.where(sm)):
                my, mx = (y, s - x) if axis == 'v' else (s - y, x)
                if 0 <= my < H and 0 <= mx < W and not hidden[my, mx]:
                    if sm[my, mx]:
                        match += 1
                    else:
                        ok = False; break
            if ok and (best is None or match > best[0]):
                best = (match, axis, s)
    if best is not None:
        _, axis, s = best
        for y, x in zip(hy, hx):
            my, mx = (y, s - x) if axis == 'v' else (s - y, x)
            out[y, x] = g[my, mx] if g[my, mx] == shape else bg
    emit(out, "Fill the hidden cells by mirroring the shape across its symmetry axis.")
    return out
